import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for ReLU
relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_kernel(const float* __restrict__ in, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        out[idx] = val > 0 ? val : 0;
    }
}

torch::Tensor relu_cuda(torch::Tensor input) {
    auto output = torch::zeros_like(input);
    int size = input.numel();
    int threads = 256;
    int blocks = (size + threads - 1) / threads;

    relu_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}
"""

relu_header = "torch::Tensor relu_cuda(torch::Tensor input);"

# Compile the custom CUDA extension
relu_module = load_inline(
    name="custom_relu",
    cpp_sources=relu_header,
    cuda_sources=relu_source,
    functions=["relu_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model: Uses standard ConvTranspose3d, but ReLU is replaced with a custom CUDA kernel.
    Then applies group normalization.
    """
    def __init__(self, in_channels, out_channels, kernel_size, groups, bias=False):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, bias=bias)
        self.group_norm = nn.GroupNorm(num_groups=groups, num_channels=out_channels)
        self.relu_module = relu_module

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.relu_module.relu_cuda(x)
        x = self.group_norm(x)
        return x

